31|  /* CRC32 */
32|  crc32_combine_gen(op, buffSize);
33|  for (offset = 0; offset + buffSize <= dataLen; offset += buffSize) {
34|    uint32_t crc3 = crc32_z(crc0, data + offset, buffSize);
35|    uint32_t crc4 = crc32_combine_op(crc1, crc3, op);
36|    crc1 = crc32_z(crc1, data + offset, buffSize);
